using System;using System.Linq;using System.IO;using System.Collections.Generic;using System.Xml.Serialization;using System.Windows.Forms;using MakroSoundSwitch;
class ReconnectBackend:IFeatureBackend{public List<Device> Devices;public List<string> Applied=new List<string>();public List<Device> ListDevices(int flow){return Devices;}public string GetDefault(int flow,int role){return "original";}public void SetDefault(string id,int role){Applied.Add(id);}public void SendMedia(FeatureType type){}public void Mute(){}}
class DeviceReconnectVerify{
 static void Assert(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS: "+text);}
 [STAThread]static void Main(){Application.EnableVisualStyles();var feature=new ScenarioFeature{Type=FeatureType.Output,DeviceId="old-id"};var scenario=new Scenario{Output="old-id",Features=new List<ScenarioFeature>{feature}};var settings=new Settings{Scenarios=new List<Scenario>{scenario}};var disconnected=new List<Device>{new Device{Id="old-id",Name="My headset",State=8}};
 Assert(DeviceBinding.Reconcile(settings,disconnected,new List<Device>())&&feature.DeviceName=="My headset"&&feature.DeviceId=="old-id","Boot without headset remembers its registered name and selected ID");Assert(DeviceBinding.Resolve(feature,disconnected)==null,"Disconnected device is not used as a connected output");var connected=new List<Device>{new Device{Id="old-id",Name="My headset"}};Assert(DeviceBinding.Resolve(feature,connected).Id=="old-id","Reconnecting same endpoint is recognized");var reinstalled=new List<Device>{new Device{Id="new-id",Name="My headset"}};Assert(DeviceBinding.Reconcile(settings,reinstalled,new List<Device>())&&feature.DeviceId=="new-id"&&scenario.Output=="new-id","Unique matching name repairs a changed endpoint ID and legacy field");
 var duplicate=new List<Device>{new Device{Id="other1",Name="My headset"},new Device{Id="other2",Name="My headset"}};feature.DeviceId="missing-id";Assert(DeviceBinding.Resolve(feature,duplicate)==null,"Two matching connected devices never trigger an arbitrary replacement");feature.DeviceId="other2";Assert(DeviceBinding.Resolve(feature,duplicate).Id=="other2","Exact endpoint ID takes priority over duplicate names");
 using(var stream=new MemoryStream()){var xml=new XmlSerializer(typeof(Settings));xml.Serialize(stream,settings);stream.Position=0;Assert(((Settings)xml.Deserialize(stream)).Scenarios[0].Features[0].DeviceName=="My headset","Remembered device name survives config save/reload");}
 var backend=new ReconnectBackend{Devices=reinstalled};var binding=new ScenarioFeature{Type=FeatureType.Output,DeviceId="old-id",DeviceName="My headset"};FeatureRunner.Run(new Scenario{Features=new List<ScenarioFeature>{binding}},backend);Assert(backend.Applied.SequenceEqual(new[]{"new-id","new-id","new-id"}),"Shortcut execution resolves reconnected device even before UI refresh");
 var choices=new List<Device>();using(var row=new FeatureRow(binding,choices,new List<Device>())){Assert(row.Value.DeviceId=="old-id"&&row.Value.DeviceName=="My headset","Editing while disconnected retains the intended device");choices.AddRange(reinstalled);row.RefreshDevices();Assert(row.Value.DeviceId=="new-id","Open editor reconnects dropdown selection automatically");choices.Clear();row.RefreshDevices();Assert(row.Value.DeviceId=="new-id"&&row.Value.DeviceName=="My headset","Unplugging in editor preserves selection instead of choosing another device");}
 using(var row=new FeatureRow(binding,reinstalled,new List<Device>()))Assert(row.Value.DeviceId=="new-id","Editor also resolves a changed ID immediately when opened");
 }
}
